/**
 * What a build is, generated by `scripts/build-info.mjs` into `resources/build-info.json`
 * (`0.0.0-dev+<sha>[.dirty]` for local builds, `X.Y.Z` plus the Actions run number for releases).
 */
export interface BuildInfo {
  version: string
  /** The GitHub Actions run number; `null` for local builds. */
  buildNumber: number | null
  commit: string | null
  dirty: boolean
  /** ISO timestamp; `null` when the build-info file is missing. */
  buildDate: string | null
}

/** `"1.2.3 (build 45)"` for releases, the plain version (`"0.0.0-dev+abc1234.dirty"`) otherwise. */
export function formatFullVersion(info: Pick<BuildInfo, 'version' | 'buildNumber'>): string {
  return info.buildNumber === null ? info.version : `${info.version} (build ${info.buildNumber})`
}

/** Validates the parsed build-info file; `null` when it isn't one. */
export function parseBuildInfo(raw: unknown): BuildInfo | null {
  if (typeof raw !== 'object' || raw === null) return null
  const { version, buildNumber, commit, dirty, buildDate } = raw as Record<string, unknown>
  if (typeof version !== 'string' || version === '') return null
  if (buildNumber !== null && typeof buildNumber !== 'number') return null
  if (commit !== null && typeof commit !== 'string') return null
  if (typeof dirty !== 'boolean') return null
  if (typeof buildDate !== 'string') return null
  return { version, buildNumber, commit, dirty, buildDate }
}
